cmd:
for s in chan-orders chan-orders-afd chan-orders-combo; do systemctl disable --now $s 2>&1 | tail -1; echo $s=$(systemctl is-active $s) enabled=$(systemctl is-enabled $s); done; python3 -c "
import json
for d in ('positions','positions_afd','positions_combo','positions_regr'):
    try:
        ps=json.load(open('/opt/trading-bot/'+d+'/positions.json'))
        print(d,'open positions:',[(p['id'],p['sym']) for p in ps if p['status']=='open'])
    except Exception as e: print(d,'n/a')
" 2>&1 | LC_ALL=C tr -cd '\11\12\40-\176'
